mapper.select:
WITH item_aggregate AS ( SELECT b.shipment_id ,SUM(ISNULL(b.qty, 0)) AS qty ,COUNT(b.lot_no) AS lot_no_count ,SUM(ISNULL(b.pallet, 0)) AS pallet FROM tb_shipment_item b GROUP BY b.shipment_id ), item_distinct AS ( SELECT DISTINCT b.shipment_id ,b.po_no ,b.item_cd ,i.item_name FROM tb_shipment_item b INNER JOIN tb_item_mst i ON i.item_cd = b.item_cd ), item_rank AS ( SELECT shipment_id ,po_no ,item_cd ,item_name ,ROW_NUMBER() OVER (PARTITION BY shipment_id ORDER BY CASE WHEN po_no IS NULL OR po_no = '' THEN 1 ELSE 0 END, po_no, item_cd ) AS rn ,COUNT(*) OVER (PARTITION BY shipment_id ) AS item_count ,COUNT( CASE WHEN po_no IS NOT NULL AND po_no <> '' THEN 1 END) OVER (PARTITION BY shipment_id) AS po_count FROM item_distinct ), item_summary AS ( SELECT shipment_id ,CASE WHEN po_count > 1 THEN CONCAT(po_no, ' 외 ', po_count - 1, '건') WHEN po_count = 1 THEN po_no ELSE '' END AS po_no ,CASE WHEN item_count > 1 THEN CONCAT(item_cd, ' 외 ', item_count - 1, '건') ELSE item_cd END AS item_cd ,CASE WHEN item_count > 1 THEN CONCAT(item_name, ' 외 ', item_count - 1, '건') ELSE item_name END AS item_name FROM item_rank WHERE rn = 1 )
SELECT CONCAT(CONVERT(VARCHAR(10), a.shipment_date, 23), ' - ', a.seq ) AS shipmentDateSeq ,a.shipment_req_date ,c1.business_manager_name ,c.client_name ,s.po_no ,s.item_cd ,s.item_name ,a.delivery_manager_name ,ag.qty ,ag.lot_no_count AS lotNo ,ag.pallet ,a.shipment_time ,a.delivery_location ,a.shipment_type ,c3.code_nm as shipment_type_name ,ISNULL(a.print_yn, 'N') AS print_yn ,a.shipment_status ,c2.code_nm as shipment_status_name ,a.shipment_yn ,a.shipment_id FROM tb_shipment_mst a left JOIN item_aggregate ag ON ag.shipment_id = a.shipment_id left JOIN item_summary s ON s.shipment_id = a.shipment_id LEFT JOIN tb_client_mst c ON c.client_id = a.client_id LEFT JOIN tb_client_Manager c1 ON c1.client_id = a.client_id and c1.order_dist = 1 left join tb_common_code c2 on c2.code = a.shipment_status and c2.com_type_cd = 'shipment_status' left join tb_common_code c3 on c3.code = a.shipment_type and c3.com_type_cd = 'shipment_type' WHERE a.shipment_date BETWEEN #{strDate} AND #{endDate}
AND a.shipment_req_date BETWEEN #{strReqDate} AND #{endReqDate}
AND c.client_name LIKE CONCAT('%', #{clientName}, '%')
AND EXISTS ( SELECT 1 FROM tb_shipment_item x WHERE x.shipment_id = a.shipment_id AND x.po_no LIKE CONCAT('%', #{poNo}, '%') )
AND EXISTS ( SELECT 1 FROM tb_shipment_item x WHERE x.shipment_id = a.shipment_id AND x.item_cd LIKE CONCAT('%', #{itemCd}, '%') )
AND EXISTS ( SELECT 1 FROM tb_shipment_item x INNER JOIN tb_item_mst xi ON xi.item_cd = x.item_cd WHERE x.shipment_id = a.shipment_id AND xi.item_name LIKE CONCAT('%', #{itemName}, '%') )
AND a.delivery_manager_name LIKE CONCAT('%', #{deliveryManagerName}, '%')
ORDER BY a.shipment_date DESC, a.seq DESC;

mapper.update:
UPDATE tb_shipment_mst
SET    shipment_req_date      = #{shipmentReqDate}
      ,shipment_time          = #{shipmentTime}
      ,client_id              = #{clientId}
      ,delivery_location      = #{deliveryLocation}
      ,delivery_address       = #{deliveryAddress}
      ,delivery_manager_name  = #{deliveryManagerName}
      ,delivery_telno         = #{deliveryTelno}
      ,shipment_type          = #{shipmentType}
      ,shipment_yn            = #{shipmentYn}
      ,managed_item           = #{managedItem}
      ,attach_file_id         = #{attachFileId}
      ,shipment_status        = #{shipmentStatus}
      ,etc                    = #{etc}
      ,upd_id                 = #{userId}
      ,upd_dt                 = GETDATE()
WHERE shipment_id            = #{shipmentId}

UPDATE tb_shipment_item
SET    qty              = #{qty}
      ,upd_id           = #{userId}
      ,upd_dt           = GETDATE()
WHERE shipment_item_id = #{shipmentItemId}

